package jp.yaegaki.equipment;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import org.json.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class GeminiTest {
 static JSONObject response(JSONArray rows)throws Exception{return new JSONObject().put("candidates",new JSONArray().put(new JSONObject().put("finishReason","STOP").put("content",new JSONObject().put("parts",new JSONArray().put(new JSONObject().put("text",new JSONObject().put("fields",rows).put("summary","確認してください").toString()))))));}
 static JSONObject row(String key,String value)throws Exception{return new JSONObject().put("key",key).put("value",value).put("confidence","high").put("evidence","銘板");}
 @Test public void rejectSecretsInvalidNetworkAndDuplicateFields()throws Exception{JSONArray rows=new JSONArray().put(row("maker","BUFFALO")).put(row("maker","Other")).put(row("password","secret")).put(row("login","admin")).put(row("mac","AA:BB:CC:DD:EE:FF")).put(row("ip","999.1.2.3")).put(row("url","https://admin:secret@example.com/")).put(row("price","推定5000円"));JSONArray parsed=Gemini.parseResponse(response(rows)).getJSONArray("fields");assertEquals(2,parsed.length());assertEquals("maker",parsed.getJSONObject(0).getString("key"));assertEquals("mac",parsed.getJSONObject(1).getString("key"));}
 @Test public void partialResponseNeverApplied()throws Exception{JSONObject r=response(new JSONArray().put(row("maker","DELL")));r.getJSONArray("candidates").getJSONObject(0).put("finishReason","MAX_TOKENS");try{Gemini.parseResponse(r);fail();}catch(Exception expected){}}
 @Test public void requestContainsOnlyPromptAndSelectedPhotos()throws Exception{JSONObject r=Gemini.request(Arrays.asList(new byte[]{1,2,3},new byte[]{4,5}));JSONArray parts=r.getJSONArray("contents").getJSONObject(0).getJSONArray("parts");assertEquals(3,parts.length());assertEquals("AQID",parts.getJSONObject(1).getJSONObject("inlineData").getString("data"));assertFalse(r.has("apiKey"));assertFalse(r.has("device"));}
 @Test public void apiKeySettingsEncryptedAndNotBackedUp()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();c.deleteDatabase("equipment.db");javax.crypto.KeyGenerator kg=javax.crypto.KeyGenerator.getInstance("AES");kg.init(256);Store s=new Store(c,kg.generateKey());s.aiSettings(new JSONObject().put("key","synthetic-test-key").put("model","gemini-2.5-flash"));assertEquals("synthetic-test-key",s.aiSettings().getString("key"));byte[] disk=java.nio.file.Files.readAllBytes(new java.io.File(c.getFilesDir(),"ai-settings").toPath());assertFalse(new String(disk,"ISO-8859-1").contains("synthetic-test-key"));java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();s.exportBackup(out,"test-password".toCharArray());byte[] backup=out.toByteArray();byte[] clear=Crypto.decrypt(Arrays.copyOfRange(backup,22,backup.length),Crypto.passwordKey("test-password".toCharArray(),Arrays.copyOfRange(backup,6,22)));try(java.util.zip.ZipInputStream z=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(clear))){java.util.zip.ZipEntry entry;while((entry=z.getNextEntry())!=null){assertEquals("manifest.json",entry.getName());assertFalse(new String(Store.limited(z,1024*1024),"UTF-8").contains("synthetic-test-key"));}}s.close();}
}
